-- без описания и у мода (только название — русское, из конфига)
for _, e in ipairs({ { "item", " Clear Case " }, { "item", "my story null tears" }, { "item", "Dogboard" }, { "item", "Moonbeam" } }) do
	DATA[#DATA + 1] = { e[1], e[2], "" }
end
-- Кнопки-«шипы» (Stud): 1…6 в одной ячейке — одно описание
local STUD = "{{ffStud}} Кладёт на пол пенни-кнопку#{{Coin}} Пенни-кнопка стоит 1 монету и ранит врагов касанием#{{Collectible486}} При подборе наносит Исааку ложный урон#В одной ячейке карт можно сложить до 6 кнопок"
for _, nm in ipairs({ "Stud", "2 Studs", "3 Studs", "4 Studs", "5 Studs", "6 Studs" }) do DATA[#DATA + 1] = { "card", nm, STUD } end
-- Накопительная и разъеденная батарейки: 4 уровня заряда у каждой
local KEEP = "{{Battery}} Сохраняет заряд активного артефакта Исаака#Повторное использование заряжает артефакт обратно#{{Collectible63}} Может зарядить сверх полного"
for i, nm in ipairs({ "Storage Battery", "Storage Battery (1)", "Storage Battery (2)", "Storage Battery (Full)" }) do
	DATA[#DATA + 1] = { "card", nm, KEEP .. "#{{Card" .. (256 + i) .. "}} В начале этажа разъедается" }
end
for _, nm in ipairs({ "Corroded Battery", "Corroded Battery (1)", "Corroded Battery (2)", "Corroded Battery (Full)" }) do
	DATA[#DATA + 1] = { "card", nm, KEEP .. "#!!! Зарядив артефакт, вскоре взрывается" }
end
return DATA
